-- Упражнения книги 19, глава 8 (Администрирование Linux). Файл строит автор-скрипт (не в репозитории); после правок можно редактировать и вручную.

INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (19, 8, 'la8-inspect-summary', 0, 'func', 'Сводка из docker inspect', 'Напишите функцию inspect_summary(text): text - вывод docker inspect для одного контейнера (JSON-массив из одного объекта, как печатает команда). Верните словарь с ключами: memory_mb - HostConfig.Memory в целых МиБ (деление вниз), None если лимита нет (0); cpus - HostConfig.NanoCpus / 1e9, округлённое до 2 знаков, None если 0; pids - HostConfig.PidsLimit, None если он null, 0 или отрицательный; oom_killed - State.OOMKilled; exit_code - State.ExitCode; ip - первый непустой IPAddress среди NetworkSettings.Networks, сети перебираются в алфавитном порядке имён, иначе пустая строка; rw_binds - отсортированный список Destination всех монтирований с Type bind и RW true.', 'def inspect_summary(text):
    pass
', 'json.loads(text)[0]; сети - sorted(nets); для memory_mb не забудьте случай 0.', '{"func": "inspect_summary", "tests": [{"args": ["[\n    {\n        \"Id\": \"3f4a1b2c9d0e8a7b6c5d4e3f2a1b0c9d8e7f6a5b4c3d2e1f0a9b8c7d6e5f4a3b\",\n        \"Name\": \"/web\",\n        \"State\": {\n            \"Status\": \"running\",\n            \"Running\": true,\n            \"Paused\": false,\n            \"Restarting\": false,\n            \"OOMKilled\": false,\n            \"Dead\": false,\n            \"Pid\": 4021,\n            \"ExitCode\": 0,\n            \"Error\": \"\",\n            \"StartedAt\": \"2026-11-03T09:00:00.123456789Z\",\n            \"FinishedAt\": \"0001-01-01T00:00:00Z\"\n        },\n        \"Image\": \"sha256:6e4f1c0a9b8d7c6e5f4a3b2c1d0e9f8a7b6c5d4e3f2a1b0c9d8e7f6a5b4c3d2e\",\n        \"HostConfig\": {\n            \"NetworkMode\": \"bridge\",\n            \"RestartPolicy\": {\n                \"Name\": \"no\",\n                \"MaximumRetryCount\": 0\n            },\n            \"CpuShares\": 0,\n            \"Memory\": 536870912,\n            \"MemorySwap\": 1073741824,\n            \"NanoCpus\": 1500000000,\n            \"CgroupParent\": \"\",\n            \"PidsLimit\": 100\n        },\n        \"GraphDriver\": {\n            \"Data\": {\n                \"LowerDir\": \"/var/lib/docker/overlay2/a1b2-init/diff:/var/lib/docker/overlay2/c3d4/diff\",\n                \"MergedDir\": \"/var/lib/docker/overlay2/a1b2/merged\",\n                \"UpperDir\": \"/var/lib/docker/overlay2/a1b2/diff\",\n                \"WorkDir\": \"/var/lib/docker/overlay2/a1b2/work\"\n            },\n            \"Name\": \"overlay2\"\n        },\n        \"Mounts\": [\n            {\n                \"Type\": \"bind\",\n                \"Source\": \"/srv/www\",\n                \"Destination\": \"/usr/share/nginx/html\",\n                \"Mode\": \"ro\",\n                \"RW\": false,\n                \"Propagation\": \"rprivate\"\n            },\n            {\n                \"Type\": \"bind\",\n                \"Source\": \"/srv/uploads\",\n                \"Destination\": \"/uploads\",\n                \"Mode\": \"\",\n                \"RW\": true,\n                \"Propagation\": \"rprivate\"\n            },\n            {\n                \"Type\": \"volume\",\n                \"Source\": \"/var/lib/docker/volumes/dbdata/_data\",\n                \"Destination\": \"/var/lib/mysql\",\n                \"Mode\": \"\",\n                \"RW\": true,\n                \"Propagation\": \"rprivate\",\n                \"Name\": \"dbdata\",\n                \"Driver\": \"local\"\n            }\n        ],\n        \"NetworkSettings\": {\n            \"Bridge\": \"\",\n            \"Ports\": {\n                \"80/tcp\": [\n                    {\n                        \"HostIp\": \"0.0.0.0\",\n                        \"HostPort\": \"8080\"\n                    }\n                ]\n            },\n            \"Networks\": {\n                \"bridge\": {\n                    \"Gateway\": \"172.17.0.1\",\n                    \"IPAddress\": \"172.17.0.2\",\n                    \"IPPrefixLen\": 16,\n                    \"MacAddress\": \"02:42:ac:11:00:02\"\n                }\n            }\n        }\n    }\n]\n"], "expected": {"memory_mb": 512, "cpus": 1.5, "pids": 100, "oom_killed": false, "exit_code": 0, "ip": "172.17.0.2", "rw_binds": ["/uploads"]}}, {"args": ["[\n    {\n        \"Id\": \"3f4a1b2c9d0e8a7b6c5d4e3f2a1b0c9d8e7f6a5b4c3d2e1f0a9b8c7d6e5f4a3b\",\n        \"Name\": \"/web\",\n        \"State\": {\n            \"Status\": \"exited\",\n            \"Running\": false,\n            \"Paused\": false,\n            \"Restarting\": false,\n            \"OOMKilled\": true,\n            \"Dead\": false,\n            \"Pid\": 0,\n            \"ExitCode\": 137,\n            \"Error\": \"\",\n            \"StartedAt\": \"2026-11-03T09:00:00.123456789Z\",\n            \"FinishedAt\": \"0001-01-01T00:00:00Z\"\n        },\n        \"Image\": \"sha256:6e4f1c0a9b8d7c6e5f4a3b2c1d0e9f8a7b6c5d4e3f2a1b0c9d8e7f6a5b4c3d2e\",\n        \"HostConfig\": {\n            \"NetworkMode\": \"bridge\",\n            \"RestartPolicy\": {\n                \"Name\": \"no\",\n                \"MaximumRetryCount\": 0\n            },\n            \"CpuShares\": 0,\n            \"Memory\": 268435456,\n            \"MemorySwap\": 536870912,\n            \"NanoCpus\": 250000000,\n            \"CgroupParent\": \"\",\n            \"PidsLimit\": -1\n        },\n        \"GraphDriver\": {\n            \"Data\": {\n                \"LowerDir\": \"/var/lib/docker/overlay2/a1b2-init/diff:/var/lib/docker/overlay2/c3d4/diff\",\n                \"MergedDir\": \"/var/lib/docker/overlay2/a1b2/merged\",\n                \"UpperDir\": \"/var/lib/docker/overlay2/a1b2/diff\",\n                \"WorkDir\": \"/var/lib/docker/overlay2/a1b2/work\"\n            },\n            \"Name\": \"overlay2\"\n        },\n        \"Mounts\": [],\n        \"NetworkSettings\": {\n            \"Bridge\": \"\",\n            \"Ports\": {\n                \"80/tcp\": [\n                    {\n                        \"HostIp\": \"0.0.0.0\",\n                        \"HostPort\": \"8080\"\n                    }\n                ]\n            },\n            \"Networks\": {\n                \"bridge\": {\n                    \"Gateway\": \"172.17.0.1\",\n                    \"IPAddress\": \"\",\n                    \"IPPrefixLen\": 0,\n                    \"MacAddress\": \"\"\n                }\n            }\n        }\n    }\n]\n"], "expected": {"memory_mb": 256, "cpus": 0.25, "pids": null, "oom_killed": true, "exit_code": 137, "ip": "", "rw_binds": []}}, {"args": ["[\n    {\n        \"Id\": \"3f4a1b2c9d0e8a7b6c5d4e3f2a1b0c9d8e7f6a5b4c3d2e1f0a9b8c7d6e5f4a3b\",\n        \"Name\": \"/web\",\n        \"State\": {\n            \"Status\": \"running\",\n            \"Running\": true,\n            \"Paused\": false,\n            \"Restarting\": false,\n            \"OOMKilled\": false,\n            \"Dead\": false,\n            \"Pid\": 4021,\n            \"ExitCode\": 0,\n            \"Error\": \"\",\n            \"StartedAt\": \"2026-11-03T09:00:00.123456789Z\",\n            \"FinishedAt\": \"0001-01-01T00:00:00Z\"\n        },\n        \"Image\": \"sha256:6e4f1c0a9b8d7c6e5f4a3b2c1d0e9f8a7b6c5d4e3f2a1b0c9d8e7f6a5b4c3d2e\",\n        \"HostConfig\": {\n            \"NetworkMode\": \"bridge\",\n            \"RestartPolicy\": {\n                \"Name\": \"no\",\n                \"MaximumRetryCount\": 0\n            },\n            \"CpuShares\": 0,\n            \"Memory\": 0,\n            \"MemorySwap\": 0,\n            \"NanoCpus\": 0,\n            \"CgroupParent\": \"\",\n            \"PidsLimit\": null\n        },\n        \"GraphDriver\": {\n            \"Data\": {\n                \"LowerDir\": \"/var/lib/docker/overlay2/a1b2-init/diff:/var/lib/docker/overlay2/c3d4/diff\",\n                \"MergedDir\": \"/var/lib/docker/overlay2/a1b2/merged\",\n                \"UpperDir\": \"/var/lib/docker/overlay2/a1b2/diff\",\n                \"WorkDir\": \"/var/lib/docker/overlay2/a1b2/work\"\n            },\n            \"Name\": \"overlay2\"\n        },\n        \"Mounts\": [],\n        \"NetworkSettings\": {\n            \"Bridge\": \"\",\n            \"Ports\": {\n                \"80/tcp\": [\n                    {\n                        \"HostIp\": \"0.0.0.0\",\n                        \"HostPort\": \"8080\"\n                    }\n                ]\n            },\n            \"Networks\": {\n                \"host\": {\n                    \"Gateway\": \"\",\n                    \"IPAddress\": \"\",\n                    \"IPPrefixLen\": 0,\n                    \"MacAddress\": \"\"\n                }\n            }\n        }\n    }\n]\n"], "expected": {"memory_mb": null, "cpus": null, "pids": null, "oom_killed": false, "exit_code": 0, "ip": "", "rw_binds": []}}, {"args": ["[\n    {\n        \"Id\": \"3f4a1b2c9d0e8a7b6c5d4e3f2a1b0c9d8e7f6a5b4c3d2e1f0a9b8c7d6e5f4a3b\",\n        \"Name\": \"/web\",\n        \"State\": {\n            \"Status\": \"exited\",\n            \"Running\": false,\n            \"Paused\": false,\n            \"Restarting\": false,\n            \"OOMKilled\": false,\n            \"Dead\": false,\n            \"Pid\": 0,\n            \"ExitCode\": 1,\n            \"Error\": \"\",\n            \"StartedAt\": \"2026-11-03T09:00:00.123456789Z\",\n            \"FinishedAt\": \"0001-01-01T00:00:00Z\"\n        },\n        \"Image\": \"sha256:6e4f1c0a9b8d7c6e5f4a3b2c1d0e9f8a7b6c5d4e3f2a1b0c9d8e7f6a5b4c3d2e\",\n        \"HostConfig\": {\n            \"NetworkMode\": \"bridge\",\n            \"RestartPolicy\": {\n                \"Name\": \"no\",\n                \"MaximumRetryCount\": 0\n            },\n            \"CpuShares\": 0,\n            \"Memory\": 2147483648,\n            \"MemorySwap\": 4294967296,\n            \"NanoCpus\": 0,\n            \"CgroupParent\": \"\",\n            \"PidsLimit\": 0\n        },\n        \"GraphDriver\": {\n            \"Data\": {\n                \"LowerDir\": \"/var/lib/docker/overlay2/a1b2-init/diff:/var/lib/docker/overlay2/c3d4/diff\",\n                \"MergedDir\": \"/var/lib/docker/overlay2/a1b2/merged\",\n                \"UpperDir\": \"/var/lib/docker/overlay2/a1b2/diff\",\n                \"WorkDir\": \"/var/lib/docker/overlay2/a1b2/work\"\n            },\n            \"Name\": \"overlay2\"\n        },\n        \"Mounts\": [\n            {\n                \"Type\": \"tmpfs\",\n                \"Source\": \"\",\n                \"Destination\": \"/run\",\n                \"Mode\": \"\",\n                \"RW\": true,\n                \"Propagation\": \"rprivate\"\n            },\n            {\n                \"Type\": \"bind\",\n                \"Source\": \"/etc/ssl\",\n                \"Destination\": \"/etc/ssl\",\n                \"Mode\": \"ro\",\n                \"RW\": false,\n                \"Propagation\": \"rprivate\"\n            }\n        ],\n        \"NetworkSettings\": {\n            \"Bridge\": \"\",\n            \"Ports\": {\n                \"80/tcp\": [\n                    {\n                        \"HostIp\": \"0.0.0.0\",\n                        \"HostPort\": \"8080\"\n                    }\n                ]\n            },\n            \"Networks\": {\n                \"app_default\": {\n                    \"Gateway\": \"172.18.0.1\",\n                    \"IPAddress\": \"172.18.0.5\",\n                    \"IPPrefixLen\": 16,\n                    \"MacAddress\": \"02:42:ac:12:00:05\"\n                },\n                \"bridge\": {\n                    \"Gateway\": \"172.17.0.1\",\n                    \"IPAddress\": \"172.17.0.3\",\n                    \"IPPrefixLen\": 16,\n                    \"MacAddress\": \"02:42:ac:11:00:03\"\n                }\n            }\n        }\n    }\n]\n"], "expected": {"memory_mb": 2048, "cpus": null, "pids": null, "oom_killed": false, "exit_code": 1, "ip": "172.18.0.5", "rw_binds": []}}, {"args": ["[\n    {\n        \"Id\": \"3f4a1b2c9d0e8a7b6c5d4e3f2a1b0c9d8e7f6a5b4c3d2e1f0a9b8c7d6e5f4a3b\",\n        \"Name\": \"/web\",\n        \"State\": {\n            \"Status\": \"running\",\n            \"Running\": true,\n            \"Paused\": false,\n            \"Restarting\": false,\n            \"OOMKilled\": false,\n            \"Dead\": false,\n            \"Pid\": 4021,\n            \"ExitCode\": 0,\n            \"Error\": \"\",\n            \"StartedAt\": \"2026-11-03T09:00:00.123456789Z\",\n            \"FinishedAt\": \"0001-01-01T00:00:00Z\"\n        },\n        \"Image\": \"sha256:6e4f1c0a9b8d7c6e5f4a3b2c1d0e9f8a7b6c5d4e3f2a1b0c9d8e7f6a5b4c3d2e\",\n        \"HostConfig\": {\n            \"NetworkMode\": \"bridge\",\n            \"RestartPolicy\": {\n                \"Name\": \"no\",\n                \"MaximumRetryCount\": 0\n            },\n            \"CpuShares\": 0,\n            \"Memory\": 67108864,\n            \"MemorySwap\": 134217728,\n            \"NanoCpus\": 2000000000,\n            \"CgroupParent\": \"\",\n            \"PidsLimit\": 4096\n        },\n        \"GraphDriver\": {\n            \"Data\": {\n                \"LowerDir\": \"/var/lib/docker/overlay2/a1b2-init/diff:/var/lib/docker/overlay2/c3d4/diff\",\n                \"MergedDir\": \"/var/lib/docker/overlay2/a1b2/merged\",\n                \"UpperDir\": \"/var/lib/docker/overlay2/a1b2/diff\",\n                \"WorkDir\": \"/var/lib/docker/overlay2/a1b2/work\"\n            },\n            \"Name\": \"overlay2\"\n        },\n        \"Mounts\": [\n            {\n                \"Type\": \"bind\",\n                \"Source\": \"/var/run/docker.sock\",\n                \"Destination\": \"/var/run/docker.sock\",\n                \"Mode\": \"\",\n                \"RW\": true,\n                \"Propagation\": \"rprivate\"\n            },\n            {\n                \"Type\": \"bind\",\n                \"Source\": \"/data\",\n                \"Destination\": \"/data\",\n                \"Mode\": \"\",\n                \"RW\": true,\n                \"Propagation\": \"rprivate\"\n            }\n        ],\n        \"NetworkSettings\": {\n            \"Bridge\": \"\",\n            \"Ports\": {\n                \"80/tcp\": [\n                    {\n                        \"HostIp\": \"0.0.0.0\",\n                        \"HostPort\": \"8080\"\n                    }\n                ]\n            },\n            \"Networks\": {\n                \"bridge\": {\n                    \"Gateway\": \"172.17.0.1\",\n                    \"IPAddress\": \"172.17.0.2\",\n                    \"IPPrefixLen\": 16,\n                    \"MacAddress\": \"02:42:ac:11:00:02\"\n                }\n            }\n        }\n    }\n]\n"], "expected": {"memory_mb": 64, "cpus": 2.0, "pids": 4096, "oom_killed": false, "exit_code": 0, "ip": "172.17.0.2", "rw_binds": ["/data", "/var/run/docker.sock"]}}, {"args": ["[\n    {\n        \"Id\": \"3f4a1b2c9d0e8a7b6c5d4e3f2a1b0c9d8e7f6a5b4c3d2e1f0a9b8c7d6e5f4a3b\",\n        \"Name\": \"/web\",\n        \"State\": {\n            \"Status\": \"running\",\n            \"Running\": true,\n            \"Paused\": false,\n            \"Restarting\": false,\n            \"OOMKilled\": false,\n            \"Dead\": false,\n            \"Pid\": 4021,\n            \"ExitCode\": 0,\n            \"Error\": \"\",\n            \"StartedAt\": \"2026-11-03T09:00:00.123456789Z\",\n            \"FinishedAt\": \"0001-01-01T00:00:00Z\"\n        },\n        \"Image\": \"sha256:6e4f1c0a9b8d7c6e5f4a3b2c1d0e9f8a7b6c5d4e3f2a1b0c9d8e7f6a5b4c3d2e\",\n        \"HostConfig\": {\n            \"NetworkMode\": \"bridge\",\n            \"RestartPolicy\": {\n                \"Name\": \"no\",\n                \"MaximumRetryCount\": 0\n            },\n            \"CpuShares\": 0,\n            \"Memory\": 0,\n            \"MemorySwap\": 0,\n            \"NanoCpus\": 0,\n            \"CgroupParent\": \"\",\n            \"PidsLimit\": null\n        },\n        \"GraphDriver\": {\n            \"Data\": {\n                \"LowerDir\": \"/var/lib/docker/overlay2/a1b2-init/diff:/var/lib/docker/overlay2/c3d4/diff\",\n                \"MergedDir\": \"/var/lib/docker/overlay2/a1b2/merged\",\n                \"UpperDir\": \"/var/lib/docker/overlay2/a1b2/diff\",\n                \"WorkDir\": \"/var/lib/docker/overlay2/a1b2/work\"\n            },\n            \"Name\": \"overlay2\"\n        },\n        \"Mounts\": [],\n        \"NetworkSettings\": {\n            \"Bridge\": \"\",\n            \"Ports\": {\n                \"80/tcp\": [\n                    {\n                        \"HostIp\": \"0.0.0.0\",\n                        \"HostPort\": \"8080\"\n                    }\n                ]\n            },\n            \"Networks\": {\n                \"bridge\": {\n                    \"Gateway\": \"172.17.0.1\",\n                    \"IPAddress\": \"172.17.0.2\",\n                    \"IPPrefixLen\": 16,\n                    \"MacAddress\": \"02:42:ac:11:00:02\"\n                }\n            }\n        }\n    }\n]\n"], "expected": {"memory_mb": null, "cpus": null, "pids": null, "oom_killed": false, "exit_code": 0, "ip": "172.17.0.2", "rw_binds": []}}]}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (19, 8, 'la8-stats-report', 1, 'func', 'Отчёт docker stats', 'Напишите функцию stats_report(text, cpu_pct, mem_pct): text - вывод docker stats --no-stream с заголовком CONTAINER ID, NAME, CPU %, MEM USAGE / LIMIT, MEM %, NET I/O, BLOCK I/O, PIDS; столбцы разделены двумя и более пробелами, внутри столбца одиночные пробелы возможны. Верните словарь: hot - имена контейнеров в порядке таблицы, у которых CPU % не меньше cpu_pct или MEM % не меньше mem_pct; used_mib - сумма использованной памяти (часть до /) всех контейнеров в МиБ, округлённая до 1 знака. Единицы памяти: B, KiB, MiB, GiB, TiB (по 1024); значение может быть дробным.', 'def stats_report(text, cpu_pct, mem_pct):
    pass
', 're.split(r''\s{2,}'', line.strip()) даёт столбцы; память переводите в МиБ через словарь единиц.', '{"func": "stats_report", "tests": [{"args": ["CONTAINER ID   NAME     CPU %    MEM USAGE / LIMIT   MEM %    NET I/O         BLOCK I/O        PIDS\n3f4a1b2c9d0e   web      0.15%    12.5MiB / 512MiB    2.44%    1.2kB / 648B    0B / 8.19kB      5\na81c0d7e2b44   db       3.20%    1.1GiB / 2GiB       55.00%   5.4MB / 3.1MB   120MB / 45.1MB   38\n77aa90bb12cd   worker   96.40%   256MiB / 1GiB       25.00%   0B / 0B         0B / 0B          12\n", 90, 50], "expected": {"hot": ["db", "worker"], "used_mib": 1394.9}}, {"args": ["CONTAINER ID   NAME     CPU %    MEM USAGE / LIMIT   MEM %    NET I/O         BLOCK I/O        PIDS\n3f4a1b2c9d0e   web      0.15%    12.5MiB / 512MiB    2.44%    1.2kB / 648B    0B / 8.19kB      5\na81c0d7e2b44   db       3.20%    1.1GiB / 2GiB       55.00%   5.4MB / 3.1MB   120MB / 45.1MB   38\n77aa90bb12cd   worker   96.40%   256MiB / 1GiB       25.00%   0B / 0B         0B / 0B          12\n", 100, 100], "expected": {"hot": [], "used_mib": 1394.9}}, {"args": ["CONTAINER ID   NAME          CPU %    MEM USAGE / LIMIT   MEM %    NET I/O          BLOCK I/O    PIDS\n0123456789ab   cache         0.05%    1.5MiB / 15.62GiB   0.01%    656B / 0B        0B / 0B      4\nba9876543210   api-gateway   12.00%   900MiB / 1GiB       87.89%   10.2MB / 9.8MB   1.2MB / 0B   210\n", 50, 80], "expected": {"hot": ["api-gateway"], "used_mib": 901.5}}, {"args": ["CONTAINER ID   NAME          CPU %   MEM USAGE / LIMIT   MEM %   NET I/O   BLOCK I/O    PIDS\nffeeddccbbaa   stopped-one   0.00%   0B / 0B             0.00%   0B / 0B   0B / 0B      0\n112233445566   tiny          0.00%   512KiB / 64MiB      0.78%   0B / 0B   4.1kB / 0B   1\n", 0.01, 101], "expected": {"hot": [], "used_mib": 0.5}}, {"args": ["CONTAINER ID   NAME          CPU %   MEM USAGE / LIMIT   MEM %   NET I/O   BLOCK I/O    PIDS\nffeeddccbbaa   stopped-one   0.00%   0B / 0B             0.00%   0B / 0B   0B / 0B      0\n112233445566   tiny          0.00%   512KiB / 64MiB      0.78%   0B / 0B   4.1kB / 0B   1\n", 0, 0], "expected": {"hot": ["stopped-one", "tiny"], "used_mib": 0.5}}, {"args": ["CONTAINER ID   NAME   CPU %    MEM USAGE / LIMIT   MEM %    NET I/O     BLOCK I/O   PIDS\naaaaaaaaaaaa   a      50.00%   1GiB / 4GiB         25.00%   1kB / 1kB   0B / 0B     3\nbbbbbbbbbbbb   b      49.99%   2GiB / 4GiB         50.00%   1kB / 1kB   0B / 0B     3\ncccccccccccc   c      10.00%   3.5GiB / 4GiB       87.50%   1kB / 1kB   0B / 0B     3\n", 50, 87.5], "expected": {"hot": ["a", "c"], "used_mib": 6656.0}}, {"args": ["CONTAINER ID   NAME   CPU %    MEM USAGE / LIMIT   MEM %    NET I/O     BLOCK I/O   PIDS\naaaaaaaaaaaa   a      50.00%   1GiB / 4GiB         25.00%   1kB / 1kB   0B / 0B     3\nbbbbbbbbbbbb   b      49.99%   2GiB / 4GiB         50.00%   1kB / 1kB   0B / 0B     3\ncccccccccccc   c      10.00%   3.5GiB / 4GiB       87.50%   1kB / 1kB   0B / 0B     3\n", 49.99, 100], "expected": {"hot": ["a", "b"], "used_mib": 6656.0}}]}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (19, 8, 'la8-ps-ports', 2, 'func', 'Порты из docker ps', 'Напишите функцию published_ports(text): text - вывод docker ps с заголовком CONTAINER ID, IMAGE, COMMAND, CREATED, STATUS, PORTS, NAMES. Столбцы выровнены пробелами, значения могут содержать пробелы и быть пустыми, поэтому режьте строки по позициям слов заголовка. Верните словарь {имя: отсортированный список уникальных номеров хост-портов} только для контейнеров, у которых STATUS начинается с Up. Опубликованный порт - элемент вида 0.0.0.0:8080->80/tcp, [::]:8080->80/tcp или 127.0.0.1:5353->53/udp; хост-порт может быть диапазоном 9000-9002 (тогда включите все порты диапазона). Элементы без -> (например 3306/tcp) пропускайте. Контейнер без опубликованных портов получает пустой список. Пустая таблица даёт {}.', 'def published_ports(text):
    pass
', 'header.index(''STATUS'') и так далее дают границы столбцов; хост-порт - то, что после последнего '':'' в левой части до ''->''.', '{"func": "published_ports", "tests": [{"args": ["CONTAINER ID   IMAGE          COMMAND                   CREATED       STATUS                       PORTS                                                                          NAMES\n3f4a1b2c9d0e   nginx:1.27     \"/docker-entrypoint.…\"    3 hours ago   Up 3 hours                   0.0.0.0:8080->80/tcp, [::]:8080->80/tcp                                        web\na81c0d7e2b44   mysql:8.4      \"docker-entrypoint.s…\"    3 hours ago   Up 3 hours                   3306/tcp, 33060/tcp                                                            db\n77aa90bb12cd   redis:7        \"docker-entrypoint.s…\"    2 days ago    Exited (137) 2 minutes ago                                                                                  cache\n5566ccdd7788   traefik:v3.1   \"/entrypoint.sh --api…\"   5 days ago    Up 5 days                    0.0.0.0:80->80/tcp, [::]:80->80/tcp, 0.0.0.0:443->443/tcp, [::]:443->443/tcp   proxy\n"], "expected": {"web": [8080], "db": [], "proxy": [80, 443]}}, {"args": ["CONTAINER ID   IMAGE    COMMAND                CREATED        STATUS                       PORTS                                            NAMES\n0a0a0a0a0a0a   bind9    \"named -g\"             1 minute ago   Up 59 seconds                127.0.0.1:5353->53/udp, 127.0.0.1:5353->53/tcp   dns\n0b0b0b0b0b0b   minio    \"minio server /data\"   1 hour ago     Up About an hour (healthy)   0.0.0.0:9000-9002->9000-9002/tcp                 s3\n0c0c0c0c0c0c   alpine   \"sleep 3600\"           1 hour ago     Up 1 hour                                                                     sleeper\n"], "expected": {"dns": [5353], "s3": [9000, 9001, 9002], "sleeper": []}}, {"args": ["CONTAINER ID   IMAGE   COMMAND   CREATED   STATUS   PORTS   NAMES\n"], "expected": {}}, {"args": ["CONTAINER ID   IMAGE     COMMAND   CREATED      STATUS                  PORTS                    NAMES\n1d1d1d1d1d1d   busybox   \"sh\"      4 days ago   Exited (0) 4 days ago                            old\n2e2e2e2e2e2e   app:1     \"/app\"    4 days ago   Created                 0.0.0.0:7000->7000/tcp   never-started\n"], "expected": {}}, {"args": [""], "expected": {}}]}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (19, 8, 'la8-run-flags', 3, 'func', 'Флаги docker run в файлы cgroup', 'Напишите функцию cgroup_files(flags): flags - список строк, каждая - один флаг docker run с значением в виде --memory=512m или --memory 512m (также короткий -m 512m); другие флаги (--rm, -d, --name=web ...) игнорируйте. Верните словарь {файл cgroup v2: строка значения}. Размер: целое число с необязательным суффиксом k, m или g (степени 1024, регистр не важен, после суффикса может стоять b), без суффикса - байты. --memory (если больше 0) даёт memory.max в байтах и ещё memory.swap.max: если --memory-swap не задан или равен 0, то столько же, сколько память; если -1, то max; иначе --memory-swap минус --memory. --cpus (если больше 0) даёт cpu.max в виде ''квота 100000'', квота = round(cpus * 100000). --pids-limit даёт pids.max: число, а 0 и отрицательные значения дают max. --cpuset-cpus даёт cpuset.cpus как есть. Считайте, что на хосте есть подкачка.', 'def cgroup_files(flags):
    pass
', 're.match(r''(-{1,2}[A-Za-z-]+)(?:[= ](.*))?$'', flag); для размеров re.fullmatch(r''(\d+)([kmg]?)b?'', s.lower()).', '{"func": "cgroup_files", "tests": [{"args": [["--memory=512m", "--memory-swap=768m", "--cpus=1.5", "--pids-limit=100"]], "expected": {"memory.max": "536870912", "memory.swap.max": "268435456", "cpu.max": "150000 100000", "pids.max": "100"}}, {"args": [["-m 1g"]], "expected": {"memory.max": "1073741824", "memory.swap.max": "1073741824"}}, {"args": [["--rm", "-d", "--name=web", "--memory 256M", "--memory-swap -1"]], "expected": {"memory.max": "268435456", "memory.swap.max": "max"}}, {"args": [["--memory=6m", "--memory-swap=6m"]], "expected": {"memory.max": "6291456", "memory.swap.max": "0"}}, {"args": [["--memory-swap=1g"]], "expected": {}}, {"args": [["--cpus 0.25", "--cpuset-cpus=0-3", "--pids-limit -1"]], "expected": {"cpu.max": "25000 100000", "pids.max": "max", "cpuset.cpus": "0-3"}}, {"args": [["--memory=100000000", "--memory-swap=0", "--cpus=0", "--pids-limit=0"]], "expected": {"memory.max": "100000000", "memory.swap.max": "100000000", "pids.max": "max"}}, {"args": [[]], "expected": {}}, {"args": [["--memory=2gb", "--memory-swap=3GB", "--cpus=2"]], "expected": {"memory.max": "2147483648", "memory.swap.max": "1073741824", "cpu.max": "200000 100000"}}]}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (19, 8, 'la8-overlay-mount', 4, 'func', 'Слои из строки mount', 'Напишите функцию overlay_layers(line): line - одна строка вывода mount для overlay, например ''overlay on <каталог> type overlay (rw,relatime,lowerdir=...,upperdir=...,workdir=...)''. Опции в скобках разделены запятыми, у опции может быть значение после первого =. Имя слоя - последний компонент пути, но если путь заканчивается на diff, merged или work, то предпоследний (так .../overlay2/<id>/diff даёт <id>, а l/ABC даёт ABC). Верните словарь: id - имя слоя для смонтированного каталога (путь после ''on '' до '' type ''), layers - имена слоёв из lowerdir от самого нижнего (основа образа) к самому верхнему; помните, что в lowerdir самый верхний слой записан первым; writable - True, если есть опция upperdir. Если lowerdir нет, layers - пустой список.', 'def overlay_layers(line):
    pass
', 'Опции - line[line.rindex(''('')+1:line.rindex('')'')].split('',''); lowerdir.split('':'') и reversed.', '{"func": "overlay_layers", "tests": [{"args": ["overlay on /var/lib/docker/overlay2/9186877cdf386d0a3b016149cf30c208f326dca307529e646afce5b3f83f5304/merged type overlay (rw,relatime,lowerdir=/var/lib/docker/overlay2/l/DJA75GUWHWG7EWICFYX54FIOVT:/var/lib/docker/overlay2/l/B3WWEFKBG3PLLV737KZFIASSW7:/var/lib/docker/overlay2/l/JEYMODZYFCZFYSDABYXD5MF6YO,upperdir=/var/lib/docker/overlay2/9186877cdf386d0a3b016149cf30c208f326dca307529e646afce5b3f83f5304/diff,workdir=/var/lib/docker/overlay2/9186877cdf386d0a3b016149cf30c208f326dca307529e646afce5b3f83f5304/work)"], "expected": {"id": "9186877cdf386d0a3b016149cf30c208f326dca307529e646afce5b3f83f5304", "layers": ["JEYMODZYFCZFYSDABYXD5MF6YO", "B3WWEFKBG3PLLV737KZFIASSW7", "DJA75GUWHWG7EWICFYX54FIOVT"], "writable": true}}, {"args": ["overlay on /var/lib/docker/overlay2/abc123/merged type overlay (rw,relatime,lowerdir=l/TOP:l/MID:l/BASE,upperdir=abc123/diff,workdir=abc123/work)"], "expected": {"id": "abc123", "layers": ["BASE", "MID", "TOP"], "writable": true}}, {"args": ["overlay on /mnt/image type overlay (ro,relatime,lowerdir=/var/lib/docker/overlay2/f1/diff:/var/lib/docker/overlay2/e2/diff)"], "expected": {"id": "image", "layers": ["e2", "f1"], "writable": false}}, {"args": ["overlay on /var/lib/docker/overlay2/zz9/merged type overlay (rw,relatime,lowerdir=l/ONLY,upperdir=zz9/diff,workdir=zz9/work,index=off,xino=off)"], "expected": {"id": "zz9", "layers": ["ONLY"], "writable": true}}, {"args": ["overlay on /var/lib/docker/overlay2/q77/merged type overlay (rw,relatime,lowerdir=/var/lib/docker/overlay2/q77-init/diff:/var/lib/docker/overlay2/b2/diff:/var/lib/docker/overlay2/a1/diff,upperdir=/var/lib/docker/overlay2/q77/diff,workdir=/var/lib/docker/overlay2/q77/work)"], "expected": {"id": "q77", "layers": ["a1", "b2", "q77-init"], "writable": true}}]}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (19, 8, 'la8-overlay-sim', 5, 'func', 'Копирование при записи и whiteout', 'Смоделируйте overlayfs на файлах. Напишите функцию overlay_ops(lowers, upper, ops): lowers - список словарей {путь: содержимое} для слоёв только для чтения в порядке lowerdir (первый - самый верхний); upper - словарь записываемого слоя. Значение None в слое - это whiteout: файл с этим путём скрыт для всего, что ниже. Видимое содержимое пути берётся из первого слоя (сначала upper, потом lowers по порядку), где путь есть; если там None, файла нет. Операции: [''append'', путь, текст] - если файл виден, к нему дописывается текст: если он лежит не в upper, сначала выполняется копирование наверх (copy_ups += 1, всего файла), затем текст дописывается в upper; если файла нет (в том числе под whiteout), он создаётся в upper с этим текстом без копирования. [''rm'', путь] - если файл не виден, ничего; если путь виден в lowers (первый из lowers, где он есть, хранит не None), в upper кладётся whiteout (None); иначе путь просто удаляется из upper. Верните словарь: merged - {путь: содержимое} всех видимых файлов, copy_ups - число копирований, whiteouts - отсортированный список путей, у которых в upper стоит None.', 'def overlay_ops(lowers, upper, ops):
    pass
', 'Функция lookup(path): upper, затем lowers по порядку; ''виден в lowers'' - первый слой lowers с этим ключом хранит не None.', '{"func": "overlay_ops", "tests": [{"args": [[{"/etc/app.conf": "a=1\n", "/bin/app": "ELF"}], {}, [["append", "/etc/app.conf", "b=2\n"]]], "expected": {"merged": {"/etc/app.conf": "a=1\nb=2\n", "/bin/app": "ELF"}, "copy_ups": 1, "whiteouts": []}}, {"args": [[{"/etc/app.conf": "a=1\n"}], {}, [["append", "/etc/app.conf", "b=2\n"], ["append", "/etc/app.conf", "c=3\n"]]], "expected": {"merged": {"/etc/app.conf": "a=1\nb=2\nc=3\n"}, "copy_ups": 1, "whiteouts": []}}, {"args": [[{"/data/old": "x"}], {}, [["rm", "/data/old"]]], "expected": {"merged": {}, "copy_ups": 0, "whiteouts": ["/data/old"]}}, {"args": [[{"/data/old": "x"}], {}, [["rm", "/data/old"], ["append", "/data/old", "new"]]], "expected": {"merged": {"/data/old": "new"}, "copy_ups": 0, "whiteouts": []}}, {"args": [[{"/f": "top"}, {"/f": "base", "/g": "g"}], {}, [["append", "/f", "!"], ["rm", "/g"]]], "expected": {"merged": {"/f": "top!"}, "copy_ups": 1, "whiteouts": ["/g"]}}, {"args": [[{"/f": null}, {"/f": "hidden"}], {}, [["append", "/f", "x"]]], "expected": {"merged": {"/f": "x"}, "copy_ups": 0, "whiteouts": []}}, {"args": [[{"/f": null}, {"/f": "hidden"}], {}, [["rm", "/f"]]], "expected": {"merged": {}, "copy_ups": 0, "whiteouts": []}}, {"args": [[{"/f": null}, {"/f": "hidden"}], {"/f": "new"}, [["rm", "/f"]]], "expected": {"merged": {}, "copy_ups": 0, "whiteouts": []}}, {"args": [[], {}, [["append", "/new", "n"], ["rm", "/new"], ["rm", "/missing"]]], "expected": {"merged": {}, "copy_ups": 0, "whiteouts": []}}, {"args": [[{"/a": "1"}], {"/a": "u", "/b": "b"}, [["append", "/a", "2"], ["rm", "/b"], ["rm", "/a"]]], "expected": {"merged": {}, "copy_ups": 0, "whiteouts": ["/a"]}}]}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (19, 8, 'la8-exit-codes', 6, 'func', 'Что значит код выхода', 'Напишите функцию classify_exits(events): events - список пар (код выхода контейнера, флаг OOMKilled из docker inspect). Для каждой пары верните строку по первому подходящему правилу: код 0 - ''ok''; 125 - ''docker-error''; 126 - ''cannot-invoke''; 127 - ''not-found''; код 137 при OOMKilled равном True - ''oom-killed''; коды 129-192 означают сигнал номер код-128: 1 SIGHUP, 2 SIGINT, 3 SIGQUIT, 6 SIGABRT, 7 SIGBUS, 9 SIGKILL, 11 SIGSEGV, 13 SIGPIPE, 15 SIGTERM, для остальных номеров ''signal-N'' (N - номер сигнала); коды 1-124 - ''error-код''; все остальные (128 и больше 192) - ''exit-код''. Верните список строк в том же порядке.', 'def classify_exits(events):
    pass
', 'Порядок проверок важен: 125-127 раньше диапазона сигналов, а 137 с OOM раньше обычного SIGKILL.', '{"func": "classify_exits", "tests": [{"args": [[]], "expected": []}, {"args": [[{"__tuple__": [0, false]}]], "expected": ["ok"]}, {"args": [[{"__tuple__": [137, true]}, {"__tuple__": [137, false]}, {"__tuple__": [143, false]}]], "expected": ["oom-killed", "SIGKILL", "SIGTERM"]}, {"args": [[{"__tuple__": [139, false]}, {"__tuple__": [130, false]}, {"__tuple__": [134, false]}, {"__tuple__": [135, false]}]], "expected": ["SIGSEGV", "SIGINT", "SIGABRT", "SIGBUS"]}, {"args": [[{"__tuple__": [125, false]}, {"__tuple__": [126, false]}, {"__tuple__": [127, false]}, {"__tuple__": [1, false]}, {"__tuple__": [124, false]}]], "expected": ["docker-error", "cannot-invoke", "not-found", "error-1", "error-124"]}, {"args": [[{"__tuple__": [128, false]}, {"__tuple__": [192, false]}, {"__tuple__": [193, false]}, {"__tuple__": [255, false]}, {"__tuple__": [140, false]}]], "expected": ["exit-128", "signal-64", "exit-193", "exit-255", "signal-12"]}, {"args": [[{"__tuple__": [1, true]}, {"__tuple__": [0, true]}, {"__tuple__": [143, true]}]], "expected": ["error-1", "ok", "SIGTERM"]}]}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (19, 8, 'la8-compose-limits', 7, 'func', 'Проверка лимитов в compose', 'Напишите функцию check_limits(services, host): services - словарь {имя: {''limits'': {...}, ''reservations'': {...}}} в духе deploy.resources из compose-файла (любой из двух ключей может отсутствовать; в limits бывают cpus, memory, pids, в reservations - cpus, memory); host - {''memory_mb'': число, ''cpus'': число}. Память - строка вида ''512M'' или ''1g'' (целое число и необязательный суффикс k, m, g, регистр не важен, после суффикса может быть b; без суффикса байты, степени 1024); cpus - строка или число, например ''0.50''. Верните список проблем-строк. Для каждой службы в алфавитном порядке имён, по порядку: ''<имя>: no memory limit'', ''<имя>: no cpu limit'', ''<имя>: no pids limit'' (если соответствующего значения нет в limits); ''<имя>: memory reservation exceeds limit'' (если заданы оба и резерв больше лимита); ''<имя>: cpu reservation exceeds limit'' (так же для cpus). Затем общие проблемы: если сумма memory-лимитов всех служб (у которых он есть) больше памяти хоста - ''host: memory limits total X MiB, host has Y MiB'' (X - сумма в МиБ, деление вниз; Y - memory_mb); затем если сумма cpus-лимитов больше cpus хоста - ''host: cpu limits total X, host has Y'' (числа форматируйте через %g).', 'def check_limits(services, host):
    pass
', 'Один разбор размера mem(s) на регулярном выражении; суммы копите в том же цикле по sorted(services).', '{"func": "check_limits", "tests": [{"args": [{"web": {"limits": {"cpus": "0.50", "memory": "512M", "pids": 200}, "reservations": {"cpus": "0.25", "memory": "256M"}}}, {"memory_mb": 4096, "cpus": 4}], "expected": []}, {"args": [{"web": {}, "db": {"limits": {"memory": "1G"}}}, {"memory_mb": 8192, "cpus": 2}], "expected": ["db: no cpu limit", "db: no pids limit", "web: no memory limit", "web: no cpu limit", "web: no pids limit"]}, {"args": [{"a": {"limits": {"cpus": 1, "memory": "3g", "pids": 10}}, "b": {"limits": {"cpus": "1.5", "memory": "2048m", "pids": 10}}}, {"memory_mb": 4096, "cpus": 2}], "expected": ["host: memory limits total 5120 MiB, host has 4096 MiB", "host: cpu limits total 2.5, host has 2"]}, {"args": [{"x": {"limits": {"cpus": "0.5", "memory": "100m", "pids": 5}, "reservations": {"cpus": "1", "memory": "200m"}}}, {"memory_mb": 1024, "cpus": 1}], "expected": ["x: memory reservation exceeds limit", "x: cpu reservation exceeds limit"]}, {"args": [{"z": {"limits": {"cpus": "1", "memory": "1024k", "pids": 1}, "reservations": {"memory": "1m"}}}, {"memory_mb": 1, "cpus": 1}], "expected": []}, {"args": [{"z": {"limits": {"cpus": "1", "memory": "1073741824", "pids": 1}, "reservations": {"memory": "1gb"}}}, {"memory_mb": 1024, "cpus": 1}], "expected": []}, {"args": [{}, {"memory_mb": 1, "cpus": 1}], "expected": []}]}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (19, 8, 'la8-socket-risk', 8, 'func', 'Чем опасны флаги docker run', 'Напишите функцию socket_risk(args): args - список слов команды docker run (только опции, без образа). Верните уровень риска для хоста: ''low'', ''medium'', ''high'' или ''root-equivalent'' (берётся наибольший). Правила. root-equivalent: --privileged; привязка (bind-монтирование) с источником, чьё имя файла docker.sock (и с :ro, и без него: доступ к сокету всё равно позволяет управлять демоном); привязка корня / без ro. high: --pid=host, --net=host или --network=host; --cap-add SYS_ADMIN или ALL (регистр не важен, префикс CAP_ допустим); привязка корня / только для чтения; записываемая привязка источника /etc, /proc, /sys, /dev, /root или /var/lib/docker либо любого пути внутри них. medium: любая другая записываемая привязка. low: всё остальное (нет опций, именованные тома, привязки только для чтения). Значение флага может идти отдельным словом (-v SRC:DST) или через = (--volume=SRC:DST, --pid=host, --cap-add=ALL). Флаги тома: -v и --volume вида ИСТОЧНИК:НАЗНАЧЕНИЕ[:опции], опции через запятую, ro значит только чтение; источник привязка, если начинается с /, иначе это именованный том. --mount: пары ключ=значение через запятую; считается только type=bind, источник в source или src, только чтение при readonly (или readonly=true, ro=true, 1). Завершающий / источника игнорируйте.', 'def socket_risk(args):
    pass
', 'Обходите args по индексу: у -v, --volume, --mount и --cap-add значение берётся из следующего слова, у остальных ищите ''=''.', '{"func": "socket_risk", "tests": [{"args": [[]], "expected": "low"}, {"args": [["-v", "/var/run/docker.sock:/var/run/docker.sock"]], "expected": "root-equivalent"}, {"args": [["-d", "--volume=/run/docker.sock:/s:ro"]], "expected": "root-equivalent"}, {"args": [["-v", "dbdata:/var/lib/mysql", "-v", "/srv/www:/usr/share/nginx/html:ro"]], "expected": "low"}, {"args": [["-v", "/srv/www:/data"]], "expected": "medium"}, {"args": [["--pid=host"]], "expected": "high"}, {"args": [["--cap-add", "sys_admin"]], "expected": "high"}, {"args": [["--cap-add=CAP_NET_ADMIN"]], "expected": "low"}, {"args": [["--mount", "type=bind,source=/etc,target=/host-etc"]], "expected": "high"}, {"args": [["--mount", "type=bind,src=/etc/,dst=/h,readonly"]], "expected": "low"}, {"args": [["--privileged", "-v", "a:/b"]], "expected": "root-equivalent"}, {"args": [["-v", "/:/host"]], "expected": "root-equivalent"}, {"args": [["-v", "/:/host:ro,z"]], "expected": "high"}, {"args": [["--mount", "type=volume,source=/x,target=/y", "--network", "host"]], "expected": "low"}, {"args": [["-v", "/var/lib/docker/volumes:/v", "--rm"]], "expected": "high"}]}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (19, 8, 'la8-shared-ns', 9, 'func', 'Общие пространства имён', 'Напишите функцию shared_namespaces(listing_a, listing_b): каждый аргумент - вывод ls -l /proc/PID/ns для одного процесса, строки вида ''lrwxrwxrwx 1 root root 0 Nov  3 10:15 net -> ''net:[4026531840]'''' (кавычки вокруг цели ссылки могут отсутствовать; строку ''total 0'' и любые строки без такой ссылки пропускайте). Имя пространства - слово перед ->, включая такие, как pid_for_children; номер inode - число в квадратных скобках. Верните отсортированный список имён, которые есть в обоих выводах и у которых номер inode одинаков (такие процессы делят это пространство). Имя, которого нет в одном из выводов, не считается общим.', 'def shared_namespaces(listing_a, listing_b):
    pass
